<?php
require_once dirname(__DIR__).'/classes/Marketplace.php';Auth::initSession();StaffAccess::requirePage('marketplace');require_once dirname(__DIR__).'/includes/service_view.php';
$actor=(int)$_SESSION['user_id'];$tab=in_array($_GET['tab']??'', ['pending','all','reports','settings'],true)?$_GET['tab']:'pending';
if($tab==='settings' || (($_SERVER['REQUEST_METHOD']??'GET')==='POST' && ($_POST['action']??'')==='policy'))StaffAccess::requirePermission('marketplace_settings');
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST') {
    try {
        $action=$_POST['action']??'';$id=(int)($_POST['id']??0);
        if($action==='policy'){Marketplace::savePolicy($actor,$_POST);setFlash('success','Advertising fees and rules updated. Existing listings keep their agreed fee and duration.');}
        elseif($action==='review'){Marketplace::review($actor,$id,(string)($_POST['decision']??''),$_POST['note']??'');setFlash('success','Advertisement reviewed. Rejected, unpublished fees are refunded once.');}
        elseif($action==='resolve'){Marketplace::resolveReport($actor,$id,$_POST['note']??'');setFlash('success','Product report resolved.');}
        else throw new InvalidArgumentException('Unknown marketplace action.');
    }catch(InvalidArgumentException $e){setFlash('error',$e->getMessage());}
    catch(Throwable $e){error_log('Marketplace moderation: '.$e->getMessage());setFlash('error','Action could not be completed. Check the record before trying again.');}
    header('Location: '.SITE_URL.'/admin/marketplace?tab='.$tab);exit;
}
$page=max(1,min(100000,(int)($_GET['page']??1)));$offset=($page-1)*25;$rows=[];$available=true;$policy=Marketplace::policy();
try {
    if($tab==='reports')$rows=Database::fetchAll("SELECT r.*,l.title,l.description,l.images,l.status AS listing_status,l.user_id AS seller_id,u.full_name AS reporter_name FROM marketplace_reports r JOIN marketplace_listings l ON l.id=r.listing_id JOIN users u ON u.id=r.user_id ORDER BY CASE WHEN r.status='open' THEN 0 ELSE 1 END,r.id DESC LIMIT 26 OFFSET $offset");
    elseif($tab!=='settings'){$where=$tab==='pending'?"WHERE l.status='pending_review'":'';$rows=Database::fetchAll("SELECT l.*,u.full_name,u.phone FROM marketplace_listings l JOIN users u ON u.id=l.user_id $where ORDER BY l.id DESC LIMIT 26 OFFSET $offset");}
    else Database::fetchOne('SELECT id FROM marketplace_listings LIMIT 1');
}catch(Throwable $e){$available=false;error_log('Marketplace admin listing: '.$e->getMessage());ErrorLogger::logException($e,'marketplace',$actor,'marketplace.admin.list');}
$more=count($rows)>25;$rows=array_slice($rows,0,25);$pageTitle='Marketplace ads';include __DIR__.'/admin_header.php'; ?>
<link rel="stylesheet" href="<?= SITE_URL ?>/assets/css/member-services.css"><h1>Marketplace ads</h1><?php displayFlash(); ?>
<nav class="feature-nav"><?php foreach(['pending'=>'Awaiting review','all'=>'All advertisements','reports'=>'Product reports','settings'=>'Fees & rules'] as $key=>$label): if($key==='settings' && !StaffAccess::can('marketplace_settings'))continue; ?><a class="btn <?= $tab===$key?'btn-primary':'btn-outline-primary' ?>" href="?tab=<?= $key ?>"><?= $label ?></a><?php endforeach; ?><a class="btn btn-outline-primary" href="<?= SITE_URL ?>/marketplace" target="_blank" rel="noopener noreferrer">View public Soko</a></nav>
<p class="service-notice">Only a paid ad can be approved. Approval starts its advertising period. Rejection before publication refunds the advertising fee to the seller's available wallet earnings. Removing an already published ad does not automatically refund the fee. Product purchases are arranged with the seller via WhatsApp.</p>
<?php if(!$available): ?><div class="alert alert-warning">Hatukuweza kufungua matangazo kwa sasa. Tafadhali jaribu tena.<?php if(StaffAccess::can('error_logs')): ?> <a href="<?= SITE_URL ?>/admin/error-logs">Angalia Error Logs</a><?php endif; ?></div><?php endif; ?>
<?php if($available && !$policy['enabled'] && $tab!=='settings'): ?><div class="alert alert-info">Matangazo mapya hayajawashwa.<?php if(StaffAccess::can('marketplace_settings')): ?> <a class="btn btn-sm btn-primary" href="?tab=settings">Weka ada na washa Soko</a><?php endif; ?></div><?php endif; ?>
<?php if($tab==='settings'): ?><section class="service-card"><h2>Advertising fee and duration</h2><form method="POST"><?php featureToken(); ?><input type="hidden" name="action" value="policy"><label><input type="checkbox" name="enabled" value="1" <?= $policy['enabled']?'checked':'' ?>>Enable new advertising requests and payments</label><div class="service-grid"><div><label for="ad-fee">Advertising fee (TZS)</label><input id="ad-fee" name="fee" type="number" min="100" max="1000000" value="<?= (int)$policy['fee'] ?>" required></div><div><label for="ad-days">Days visible after approval</label><input id="ad-days" name="days" type="number" min="1" max="90" value="<?= (int)$policy['days'] ?>" required></div></div><label for="ad-rules">Rules sellers must accept</label><textarea id="ad-rules" name="rules" rows="7" maxlength="8000" required><?= sanitize($policy['rules']) ?></textarea><p>Describe permitted products, photo requirements, moderation and cancellation/refund terms. No sales or customer counts are guaranteed by the advertising fee.</p><button class="btn btn-primary">Save advertising policy</button></form></section><?php endif; ?>
<?php if(!$rows && $available && $tab!=='settings'): ?><p class="service-empty">No records found.</p><?php endif; ?>
<?php foreach($rows as $row): ?><article class="service-card">
<?php if($tab==='reports'): ?><h2>Report #<?= (int)$row['id'] ?> · <?= sanitize($row['title']) ?></h2><p>Reported by <?= sanitize($row['reporter_name']) ?> · <?= featureStatus($row['status']) ?> · Ad status <?= featureStatus($row['listing_status']) ?></p><div class="market-thumbnails"><?php foreach(Marketplace::images($row['images']) as $image): ?><a href="<?= sanitize(SITE_URL.'/'.$image) ?>" target="_blank" rel="noopener noreferrer"><img src="<?= sanitize(SITE_URL.'/'.$image) ?>" alt="Product photo" width="120" height="90"></a><?php endforeach; ?></div><p class="service-note"><?= sanitize($row['description']) ?></p><h3>Report reason</h3><p><?= sanitize($row['reason']) ?></p>
<?php if($row['status']==='open'): ?><form method="POST"><?php featureToken(); ?><input type="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Resolution note<textarea name="note" maxlength="1000" rows="2" required></textarea></label><button class="btn btn-outline-primary">Resolve report</button></form>
<?php if($row['listing_status']==='approved'): ?><form method="POST"><?php featureToken(); ?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= (int)$row['listing_id'] ?>"><input type="hidden" name="decision" value="removed"><label>Reason for removing the advertisement<textarea name="note" maxlength="1000" rows="2" required></textarea></label><button class="btn btn-outline-danger">Remove published ad</button></form><?php endif; ?>
<?php else: ?><p>Resolution: <?= sanitize($row['review_note']) ?></p><?php endif; ?>
<?php else: $expired=$row['status']==='approved' && $row['expires_at']<=gmdate('Y-m-d H:i:s'); ?>
<h2>#<?= (int)$row['id'] ?> · <?= sanitize($row['title']) ?></h2><p>Seller <?= sanitize($row['full_name']) ?> · <?= sanitize($row['phone']) ?> · <?= featureStatus($expired?'expired':$row['status']) ?></p><div class="market-gallery"><?php foreach(Marketplace::images($row['images']) as $image): ?><a href="<?= sanitize(SITE_URL.'/'.$image) ?>" target="_blank" rel="noopener noreferrer"><img src="<?= sanitize(SITE_URL.'/'.$image) ?>" alt="<?= sanitize($row['title']) ?>" width="480" height="360" loading="lazy"></a><?php endforeach; ?></div><p class="market-price"><?= formatCurrency($row['product_price']) ?></p><p><?= sanitize(Marketplace::CATEGORIES[$row['category']]??'Other') ?> · <?= sanitize($row['location']) ?> · WhatsApp <?= sanitize($row['whatsapp']) ?></p><p class="service-note"><?= sanitize($row['description']) ?></p><p class="service-budget">Fee <?= formatCurrency($row['ad_fee']) ?> · <?= featureStatus($row['fee_status']) ?> · <?= (int)$row['duration_days'] ?> days after approval<?php if($row['expires_at']): ?> · Expires <?= formatLedgerTime($row['expires_at']) ?> EAT<?php endif; ?></p>
<details><summary>Rules accepted by this seller</summary><?php $acceptedPolicy=json_decode($row['policy_snapshot'],true)?:[]; ?><p class="service-note"><?= sanitize($acceptedPolicy['rules']??'') ?></p></details>
<?php if($row['status']==='pending_review'): ?><form method="POST"><?php featureToken(); ?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Moderation findings<textarea name="note" maxlength="1000" rows="2" required></textarea></label><button class="btn btn-success" name="decision" value="approved">Approve and publish</button><button class="btn btn-outline-danger" name="decision" value="rejected">Reject and refund fee</button></form>
<?php elseif($row['status']==='approved'): ?><a class="btn btn-outline-primary" href="<?= SITE_URL ?>/product?id=<?= (int)$row['id'] ?>" target="_blank" rel="noopener noreferrer">View public ad</a><form method="POST"><?php featureToken(); ?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="decision" value="removed"><label>Reason for removal<textarea name="note" maxlength="1000" rows="2" required></textarea></label><button class="btn btn-outline-danger">Remove ad</button></form><?php endif; ?>
<?php if($row['review_note']): ?><p>Last decision: <?= sanitize($row['review_note']) ?></p><?php endif; ?>
<?php endif; ?></article><?php endforeach; ?>
<?php featurePages($page,$more,'page',['tab'=>$tab]);include __DIR__.'/admin_footer.php'; ?>
